private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    if (ignoreCase) {
        // regionMatches with ignoreCase parameter set to true
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If only one of them is null, it's not a match
    if (str == null || prefix == null) {
        return false;
    }
    // If prefix is longer than the string, it can't match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Use regionMatches for case-insensitive comparison, otherwise use startsWith
    return ignoreCase
            ? str.regionMatches(true, 0, prefix, 0, prefix.length())
            : str.startsWith(prefix);
}

